// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != address(0) && newOwner != address(this));
        // Transfer ownership to this contract (test caller)
        vm.prank(c.owner());
        c.transferOwnership(address(this));
        // Now transfer to fuzz address
        vm.prank(address(this));
        c.transferOwnership(newOwner);
        // Try calling owned() as newOwner
        vm.prank(newOwner);
        (bool ok, ) = address(c).call(abi.encodeWithSignature("owned()"));
        // In reference, ownership was transferred so call succeeds
        // In buggy, ownership stayed with this contract, so onlyOwner revert
        assertTrue(ok);
    }
}

